#!/usr/bin/env node
// Download the release binary for this platform into ./bin/.
//
// Trust model: the expected sha256 for every release asset is pinned into this package
// (bin/sums.json, generated by the release workflow from the build artifacts). npm and
// GitHub Releases are separate registries — an attacker must compromise BOTH to serve a
// substituted binary that passes verification. A checksum fetched from the same place as
// the archive would prove nothing, so none is downloaded. Set TOKENSTASH_BINARY to skip
// (e.g. brew/cargo installs).
const fs = require("fs"), path = require("path"), https = require("https"), crypto = require("crypto"), { execSync } = require("child_process");
if (process.env.TOKENSTASH_BINARY) process.exit(0);
const pkg = require("../package.json");
const plat = { darwin: "darwin", linux: "linux" }[process.platform];
const arch = { x64: "x64", arm64: "arm64" }[process.arch];
if (!plat || !arch) { console.error(`tokenstash: no prebuilt binary for ${process.platform}/${process.arch}; install with cargo: cargo install tokenstash`); process.exit(0); }
const url = `https://github.com/kgarg2468/tokenstash/releases/download/v${pkg.version}/tokenstash-${plat}-${arch}.tar.gz`;
const dest = path.join(__dirname, "tokenstash");
let expected;
try { expected = require("./sums.json")[`${plat}-${arch}`]; } catch {}
if (!expected || !/^[a-f0-9]{64}$/.test(expected)) {
  console.error("tokenstash: no pinned checksum for this platform in sums.json; refusing to install");
  process.exit(1);
}
function get(u, cb, n = 0) {
  https.get(u, (r) => {
    if ([301, 302, 303, 307, 308].includes(r.statusCode) && n < 5) return get(r.headers.location, cb, n + 1);
    if (r.statusCode !== 200) { console.error(`tokenstash: download failed (${r.statusCode}) ${u}`); process.exit(0); }
    cb(r);
  }).on("error", (e) => { console.error("tokenstash: download error:", e.message); process.exit(0); });
}
get(url, (res) => {
  // keep the download COMPRESSED: the pinned digest covers exactly these bytes
  const gz = dest + ".tar.gz";
  const out = fs.createWriteStream(gz);
  res.pipe(out).on("finish", () => {
    const actual = crypto.createHash("sha256").update(fs.readFileSync(gz)).digest("hex");
    if (!crypto.timingSafeEqual(Buffer.from(actual), Buffer.from(expected))) {
      console.error(`tokenstash: checksum mismatch — got ${actual}, want ${expected}. Not installing.`);
      try { fs.unlinkSync(gz); } catch {}
      process.exit(1);
    }
    execSync(`tar -xzf "${gz}" -C "${__dirname}"`);
    fs.unlinkSync(gz);
    fs.chmodSync(dest, 0o755);
    console.log("tokenstash: installed (checksum verified against the digest pinned in this package). Run `tokenstash init`.");
  });
});
